{"character":{"name":"角色名","work":"出处作品","canon":["官方设定要点，最多4条"]},"inspiration":[{"title":"方案名","why":"为什么适合这个角色","how":"画面怎么改：主体、镜头、光线、材质、背景","params":["--ar 3:4","--stylize 250"]}],"fill":{"requirement":"可直接写入出图需求的整句中文","referenceRole":"只借气质","usage":"个人创作","outputSize":"原图尺寸"},"confirm":[{"q":"需要你确认的点","options":["选项A","选项B"],"recommended":0}],"searchKeywords":["用于检索参考图的中文关键词"]}
